def get_route_path(scope: Scope) -> str:
    root_path = scope.get("root_path", "")
    route_path = scope["path"]
    if not route_path.startswith(root_path):
        return route_path

    if route_path == root_path:
        return ""

    if route_path[len(root_path)] == "/":
        return route_path[len(root_path) :]

    return route_path
